package edgetts

import "testing"

// Fixed vectors generated by upstream rany2/edge-tts (drm.py), kept so this
// port stays byte-for-byte compatible with the Sec-MS-GEC v2 algorithm.
func TestGenerateSecMSGECVectors(t *testing.T) {
	vectors := map[int64]string{
		1764000000: "BB2B3ADE6A8DD1F3-B07567543B86F99C3539F563D8D3368C59A22CAF50BF1E35F42DA34792F80A76",
		1764000300: "9B961BE8F45572FA-C1C7357B8D7A00CFB029F6591D95834D78CAF83EBCABDCA6721CBB775F84CE3D",
		1700000000: "2CD23A2CA0B2595A-F3C846C370E05F9CC83ACC5F995C5F5D87A4D0F14CE8936A0F902E64099E38A2",
	}
	for unixTime, want := range vectors {
		got, err := GenerateSecMSGEC(unixTime)
		if err != nil {
			t.Fatalf("GenerateSecMSGEC(%d): %v", unixTime, err)
		}
		if got != want {
			t.Errorf("GenerateSecMSGEC(%d) = %s, want %s", unixTime, got, want)
		}
	}
}
